--
-- Name: drop_roles_safely(text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.drop_roles_safely(role_names text[]) RETURNS text[]
    LANGUAGE plpgsql
    AS $$
DECLARE
    role_name text;
    dropped_roles text[] := '{}';
    current_role text;
BEGIN
    FOREACH role_name IN ARRAY role_names
    LOOP
        BEGIN
            -- Проверяем, является ли роль текущей ролью сессии
            SELECT current_user INTO current_role;
            IF role_name = current_role THEN
                RAISE NOTICE 'Нельзя удалить текущую роль сессии: %', role_name;
                CONTINUE;
            END IF;
            
            -- Пытаемся удалить роль
            IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = role_name) THEN
                EXECUTE format('DROP ROLE %I', role_name);
                dropped_roles := array_append(dropped_roles, role_name);
                RAISE NOTICE 'Успешно удалена роль: %', role_name;
            ELSE
                RAISE NOTICE 'Роль не существует: %', role_name;
            END IF;
            
        EXCEPTION 
            WHEN dependent_objects_still_exist THEN
                -- Если есть зависимости, используем CASCADE
                BEGIN
                    EXECUTE format('DROP ROLE %I CASCADE', role_name);
                    dropped_roles := array_append(dropped_roles, role_name);
                    RAISE NOTICE 'Успешно удалена роль с CASCADE: %', role_name;
                EXCEPTION 
                    WHEN OTHERS THEN
                        RAISE NOTICE 'Не удалось удалить роль % даже с CASCADE: %', role_name, SQLERRM;
                END;
            WHEN OTHERS THEN
                RAISE NOTICE 'Ошибка при удалении роли %: %', role_name, SQLERRM;
        END;
    END LOOP;
    
    RETURN dropped_roles;
END;
$$;


ALTER FUNCTION public.drop_roles_safely(role_names text[]) OWNER TO postgres;

